<?php

declare(strict_types=1);

namespace AssetOptimizer\Path;

use AssetOptimizer\Image\ImageOptimizer;
use AssetOptimizer\WatchMode;
use Symfony\Component\AssetMapper\Path\PublicAssetsFilesystemInterface;
use Symfony\Component\Filesystem\Filesystem;
use Throwable;
use function strlen;

/**
 * Decorates AssetMapper's public-assets filesystem to drop WebP and AVIF twins
 * next to each raster it writes: <name>.jpg -> <name>.jpg.webp / .jpg.avif
 * (extension appended).
 *
 * Living inside the write path means twins are generated by every compile,
 * however it was started (console command, programmatic, watch subprocess) —
 * no coupling to a command name. Incremental per format: an existing twin is
 * skipped (filenames are content hashes, so an existing twin means the content
 * is unchanged), so enabling a format later back-fills its twins without
 * re-encoding the other. A twin is only written when it is genuinely smaller
 * than what the server would otherwise pick: the raster for WebP; the raster
 * AND the on-disk WebP twin for AVIF, because the Accept rule prefers AVIF
 * when both exist. A candidate rejected as not-smaller leaves a zero-byte
 * `<twin>.skip` marker next to the raster, so the expensive encode is not
 * repeated on any later compile — same content, same config, same verdict.
 * Twins are encoded by the pinned binaries only (no GD fallback), so every
 * on-disk twin and marker is a binary-encoder verdict — apps upgrading from a
 * GD-fallback bundle version should wipe public/assets once, or GD-era twins
 * get demoted to markers as if avifenc had produced them (see README). An
 * unavailable binary skips the twin and the next compile retries. Markers
 * share the twins' lifecycle: content-hashed names, wiped with public/assets.
 */
final readonly class TwinFilesystem implements PublicAssetsFilesystemInterface
{
    private Filesystem $fs;

    public function __construct(
        private PublicAssetsFilesystemInterface $inner,
        private ImageOptimizer                  $optimizer,
        private bool                            $debug,
        private bool                            $webpEnabled,
        private int                             $webpQuality,
        private bool                            $avifEnabled,
        private int                             $avifQuality,
    )
    {
        $this->fs = new Filesystem();
    }

    public function write(string $path, string $contents): void
    {
        $this->inner->write($path, $contents);
        $this->writeTwins($path, $contents);
    }

    public function copy(string $originPath, string $path): void
    {
        $this->inner->copy($originPath, $path);
        $this->writeTwins($path, null);
    }

    public function getDestinationPath(): string
    {
        return $this->inner->getDestinationPath();
    }

    /**
     * Encodes the twins from the just-written asset and drops each next to the
     * source when it is genuinely smaller than everything it competes with.
     *
     * @param ?string $contents the just-written bytes when the caller has them
     *                          (write); null makes copy stat the file instead
     */
    private function writeTwins(string $path, ?string $contents): void
    {
        if ((!$this->webpEnabled && !$this->avifEnabled) || 1 !== preg_match('/\.(jpe?g|png)$/i', $path)) {
            return;
        }

        // Mirror ImageOptimizeCompiler's dev gate: outside a watch compile,
        // dev writes raw rasters, and encoding twins of unoptimized bytes
        // would waste encoder work on files whose digests no watch preview
        // ever references.
        if ($this->debug && !WatchMode::active()) {
            return;
        }

        $local = $this->localPath($path);

        // $local is the exact raster the twins compete with and was just
        // written, so its size is available. If it can't be read, skip rather
        // than risk shipping a twin larger than its source.
        $sourceSize = null !== $contents ? strlen($contents) : @filesize($local);
        if (false === $sourceSize) {
            return;
        }

        // Each format is best-effort in isolation: the encode, the size
        // check, or the write may break the build, and a failed format must
        // not cost the other its twin. A missing twin is fine; the Accept
        // rule serves the next candidate instead.
        if ($this->webpEnabled) {
            try {
                $this->writeWebp($path, $local, $sourceSize);
            } catch (Throwable) {
                // leave the raster without a WebP twin
            }
        }

        if ($this->avifEnabled) {
            try {
                $this->writeAvif($path, $local, $sourceSize);
            } catch (Throwable) {
                // leave the raster without an AVIF twin
            }
        }
    }

    private function writeWebp(string $path, string $local, int $sourceSize): void
    {
        if ($this->fs->exists($local . '.webp')) {
            // Content-hashed name → already converted. Except zero bytes
            // (truncated by outside tooling): that is no twin, yet the Accept
            // rule serves it on existence alone — remove it and re-encode.
            if (0 !== @filesize($local . '.webp')) {
                return;
            }
            $this->fs->remove($local . '.webp');
        }

        if ($this->fs->exists($local . '.webp.skip')) {
            return; // rejected before: same content re-encodes to the same bytes
        }

        $webp = $this->optimizer->webp($local, $this->webpQuality);
        if (null === $webp) {
            return; // encoder unavailable — no marker, may become available
        }

        if (strlen($webp) < $sourceSize) {
            $this->inner->write($path . '.webp', $webp);
        } else {
            $this->markSkipped($path, '.webp');
        }
    }

    private function writeAvif(string $path, string $local, int $sourceSize): void
    {
        // The Accept rule prefers AVIF over WebP on existence alone, so the
        // AVIF twin must beat the raster AND whatever .webp sits on disk —
        // written by this pass, an earlier compile, or before WebP was
        // disabled. Unreadable size → skip conservatively, mirroring the
        // raster rule above. Zero bytes (truncated by outside tooling) is no
        // twin at all: remove it so it stops being served; writeWebp
        // re-encodes it while the format is enabled.
        $webpSize = null;
        if ($this->fs->exists($local . '.webp')) {
            $webpSize = @filesize($local . '.webp');
            if (false === $webpSize) {
                return;
            }
            if (0 === $webpSize) {
                $this->fs->remove($local . '.webp');
                $webpSize = null;
            }
        }

        if ($this->fs->exists($local . '.avif')) {
            // Re-validate: the twin may predate a back-filled smaller .webp
            // (it was bounded by the raster alone while WebP was disabled).
            // Re-encoding cannot help — same content, same bytes — so demote
            // it to a marker and let the Accept rule fall through to WebP. A
            // failed stat is no evidence: bail and let a later compile decide.
            $avifSize = @filesize($local . '.avif');
            if (false === $avifSize) {
                return;
            }
            if (0 !== $avifSize) {
                if ($avifSize >= $sourceSize || (null !== $webpSize && $avifSize >= $webpSize)) {
                    $this->fs->remove($local . '.avif');
                    $this->markSkipped($path, '.avif');
                }

                return;
            }

            // Zero bytes is no verdict — remove the truncated twin and fall
            // through: the marker check or a fresh encode decides.
            $this->fs->remove($local . '.avif');
        }

        // After the re-validation branch, so a stray .avif coexisting with a
        // marker (compile race, deploy-tree merge) is demoted above rather
        // than served forever on existence.
        if ($this->fs->exists($local . '.avif.skip')) {
            return; // rejected before: same content re-encodes to the same bytes
        }

        $avif = $this->optimizer->avif($local, $this->avifQuality);
        if (null === $avif) {
            return; // encoder unavailable — no marker, may become available
        }

        if (strlen($avif) < $sourceSize && (null === $webpSize || strlen($avif) < $webpSize)) {
            $this->inner->write($path . '.avif', $avif);
        } else {
            $this->markSkipped($path, '.avif');
        }
    }

    /**
     * Records "candidate rejected as not smaller" with a zero-byte marker, so
     * the encode is not repeated on every compile. The verdict only holds for
     * the same content (hash), twin quality config, and encoder version —
     * hence a quality change or encoder bump needs a public/assets wipe to be
     * re-evaluated (see README).
     */
    private function markSkipped(string $path, string $twinExt): void
    {
        $this->inner->write($path . $twinExt . '.skip', '');
    }

    private function localPath(string $path): string
    {
        return $this->inner->getDestinationPath() . '/' . ltrim($path, '/');
    }
}
